import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 4 · 主动个人 Agent","description":"Hearth Stage 4 开发模块：Trigger、主动收件箱、手机 PWA、设备配对、推送脱敏、撤销、注意力预算与主动试跑。","frontmatter":{"title":"Stage 4 · 主动个人 Agent","description":"Hearth Stage 4 开发模块：Trigger、主动收件箱、手机 PWA、设备配对、推送脱敏、撤销、注意力预算与主动试跑。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4.md","filePath":"delivery/stage-4.md","lastUpdated":1793752688000}'),i={name:"delivery/stage-4.md"};function d(o,t,n,s,h,g){return e(),r("div",null,[...t[0]||(t[0]=[l('<p class="eyebrow">MODULE 4 / 7</p><h1 id="stage-4-·-主动个人-agent" tabindex="-1">Stage 4 · 主动个人 Agent <a class="header-anchor" href="#stage-4-·-主动个人-agent" aria-label="Permalink to &quot;Stage 4 · 主动个人 Agent&quot;">​</a></h1><p class="lead">让 Hearth 在有限授权内主动工作，同时保持低打扰。难点不是“能否自动运行”，而是能否在正确的时候、用正确的打扰程度做正确的事。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>Stage 1–3 的恢复、审批、验证、接管和撤销已经稳定。</li><li>用户已建立明确的注意力预算、静默时段和高风险动作边界。</li><li>主动模式默认可控、可暂停、可降级，并且有对照评估。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>接入 Trigger。</strong> 从邮件、日历、文件和任务依赖产生事件，完成去重、冷却、优先级和“为什么现在”解释。</li><li><strong>建立主动收件箱。</strong> 输出主动候选、建议动作、预算、影响和是否打扰；支持接受、忽略、暂停和转为普通任务。</li><li><strong>交付手机 PWA。</strong> 支持查看今日、需要你、产物，完成审批、接管、发起任务和高信号通知。</li><li><strong>完成安全配对与撤销。</strong> 使用短期二维码配对、公钥、nonce、参数绑定、过期时间、安全隧道或推送中继；手机丢失可立即撤销。</li><li><strong>实施注意力预算。</strong> 控制打断次数、静默时段、聚合通知、后台预算和失控循环；先 shadow/对照运行。</li><li><strong>完成 Stage 4 发布。</strong> 评估主动任务成功率、每任务打断次数、用户满意度、预算透支和安全回归。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td>D4.1 Trigger 与主动收件箱</td><td>Hearth 能解释“现在可以做什么”</td><td>事件去重、候选生成、A1/A2 边界、暂停与忽略</td></tr><tr><td>D4.2 手机 PWA</td><td>手机可查看、审批、接管、发起任务</td><td>响应式 PWA、关键动作、离线只读、推送脱敏</td></tr><tr><td>D4.3 安全配对、推送与设备撤销</td><td>手机配对简单，丢失后可立即撤销</td><td>公钥配对、nonce、过期、撤销、审计</td></tr><tr><td>D4.4 注意力预算与主动试跑</td><td>主动模式安静有用，不制造通知疲劳</td><td>打断指标、静默时段、shadow、kill switch</td></tr><tr><td>D4.5 Stage 4 发布</td><td>主动任务真实有用，关键动作手机可达</td><td>用户满意度、成功率、预算与安全评估</td></tr></tbody></table><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] 主动任务真实有用，不制造通知疲劳。</li><li>[ ] 每任务平均打断次数 ≤ 1。</li><li>[ ] 高风险动作仍需审批，手机审批不可重放。</li><li>[ ] 丢失设备可撤销，撤销后无法继续审批或接管。</li><li>[ ] 用户能随时暂停、撤销和降级主动模式；无后台无限循环或预算透支。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不在没有预算、静默和撤销机制时开放主动循环。</li><li>不让手机持有长期主凭据。</li><li>不用推送正文泄露敏感信息。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>进入 <a href="/hearth-os/delivery/stage-5.html">Stage 5 · 记忆与进化</a>，让系统积累个人上下文并安全改进方法。</p>',15)])])}const _=a(i,[["render",d]]);export{u as __pageData,_ as default};
